/**
 * Art for the branching pipeline: the junction control box, signal lights, lever,
 * dust puff, the split / merge rails, the track-switch carriage and the signpost.
 * Drawn as letter grids like the sprites (one letter = one pixel). Regular
 * structures (panel frame, rails, boards, lever) are generated by small functions
 * that output letter rows; `npm run sprites` exports everything to PNG.
 *
 * Palette letters (shared with art/themes.ts):
 *   d outline  k panel dark  m steel light  M steel  n steel shadow  w white
 *   o orange  O orange dark  c cyan  C cyan dark  g green  G green dark  j green light
 *   y yellow  Y yellow dark  q yellow light  r red  R red dark  p red light
 *   b belt  B belt dark  u wood  U wood dark  t paper  T paper shade  x dust  z dust light
 */
export const trackPalette: Record<string, string> = {
  d: "#12131a",
  k: "#1b1d27",
  m: "#8f98bd",
  M: "#6c7396",
  n: "#4a5070",
  w: "#f0f0f6",
  o: "#ff8c00",
  O: "#b35f00",
  c: "#00bfff",
  C: "#006e99",
  g: "#00ff41",
  G: "#0a9a2a",
  j: "#b8ffc8",
  y: "#ffd84a",
  Y: "#b8941a",
  q: "#fff6b0",
  r: "#ff3b3b",
  R: "#a01818",
  p: "#ffb0b0",
  b: "#1a1a22",
  B: "#111118",
  u: "#a8723f",
  U: "#6b4526",
  t: "#e8dcb8",
  T: "#b9a878",
  x: "#9aa0b0",
  z: "#d4d8e6",
};

type Cv = string[][];
const canvas = (w: number, h: number): Cv => Array.from({ length: h }, () => Array(w).fill("."));
const rows = (cv: Cv) => cv.map((r) => r.join(""));
const put = (cv: Cv, x: number, y: number, c: string) => {
  if (y >= 0 && y < cv.length && x >= 0 && x < cv[0].length) cv[y][x] = c;
};

// ---------- signal lights (8x8): a dark housing with one lamp ----------
const LAMP = [".dddddd.", "dhhaaaad", "dhaaaaad", "daaaaaad", "daaaaasd", "daaaassd", "dssssssd", ".dddddd."];
const lamp = (a: string, h: string, s: string) => LAMP.map((r) => [...r].map((c) => (c === "a" ? a : c === "h" ? h : c === "s" ? s : c)).join(""));
/** Green means "selected / visited" and always carries two extra cues besides its colour: a white ring and a white check mark. */
const GREEN_SELECTED = [".wwwwww.", "wjgggggw", "wggggwgw", "wgwgwggw", "wggwgggw", "wgggggGw", "wGGGGGGw", ".wwwwww."];
export const lights = { red: lamp("r", "p", "R"), yellow: lamp("y", "q", "Y"), green: GREEN_SELECTED };

// ---------- panel frame (24x24, 8px border: used with border-image slice 8) ----------
export const panel = (() => {
  const N = 24;
  const cv = canvas(N, N);
  for (let y = 0; y < N; y++)
    for (let x = 0; x < N; x++) {
      const e = Math.min(x, y, N - 1 - x, N - 1 - y);
      if (e >= 8) continue; // the middle stays transparent (CSS fills it)
      const lightSide = Math.min(x, y) <= Math.min(N - 1 - x, N - 1 - y);
      cv[y][x] = e === 0 ? "d" : e === 1 ? (lightSide ? "m" : "n") : e <= 5 ? "M" : e === 6 ? "n" : "k";
    }
  for (const [cx, cy] of [[3, 3], [19, 3], [3, 19], [19, 19]]) {
    put(cv, cx, cy, "w");
    put(cv, cx + 1, cy, "m");
    put(cv, cx, cy + 1, "m");
    put(cv, cx + 1, cy + 1, "n");
  }
  return rows(cv);
})();

// ---------- lever (24x24 frames): base plate with a slot, handle at an angle ----------
function leverFrame(deg: number): string[] {
  const cv = canvas(24, 24);
  const base = [
    "..dddddddddddddddddddd..",
    ".dmmmmmmmmmmmmmmmmmmmmd.",
    "dmMMMMMMMMMMMMMMMMMMMMmd",
    "dmMkkkkkkkkkkkkkkkkkkMmd",
    "dmMMMMMMMMMMMMMMMMMMMMmd",
    "dnMwMMMMMMMMMMMMMMMMwMnd",
    ".dnnnnnnnnnnnnnnnnnnnnd.",
    "..dddddddddddddddddddd..",
  ];
  base.forEach((r, i) => [...r].forEach((c, x) => c !== "." && put(cv, x, 16 + i, c)));
  const rad = (deg * Math.PI) / 180;
  const px = 12, py = 19, len = 12;
  for (let t = 0; t <= len; t += 0.5) {
    const x = Math.round(px + t * Math.sin(rad));
    const y = Math.round(py - t * Math.cos(rad));
    put(cv, x, y, "w");
    put(cv, x + 1, y, "m");
  }
  const tx = Math.round(px + (len + 1) * Math.sin(rad));
  const ty = Math.round(py - (len + 1) * Math.cos(rad));
  for (let dy = -2; dy <= 2; dy++)
    for (let dx = -2; dx <= 2; dx++) if (dx * dx + dy * dy <= 5) put(cv, tx + dx, ty + dy, dy + dx <= -2 ? "p" : dy > 0 || dx > 1 ? "R" : "r");
  put(cv, px, py - 1, "n"); // pivot bolt
  put(cv, px, py, "w");
  return rows(cv);
}
/** Seven handle poses, in sheet order: overshoot-left, left, centre (from the left), centre, centre (from the right), right, overshoot-right.
 *  A snap to position P plays three frames: the start pose, the overshoot past P, then P. */
export const leverAngles = [-50, -38, -8, 0, 8, 38, 50] as const;
export const lever = leverAngles.map(leverFrame);

// ---------- dust puff (12x12, 4 frames) ----------
export const dust = [
  ["............", "............", "............", "............", "............", "....xzzx....", "...xzzzzx...", "...zzzzzz...", "....zzzz....", "............", "............", "............"],
  ["............", "............", "............", "............", "............", ".xzz....zzx.", "xzzzx..xzzzx", ".zzzz..zzzz.", "..zz....zz..", "............", "............", "............"],
  ["............", "............", "............", "............", "............", "xz........zx", "zzx......xzz", ".zz......zz.", "............", "............", "............", "............"],
  ["............", "............", "............", "............", "............", "z..........z", ".x........x.", "............", "............", "............", "............", "............"],
];

// ---------- rails: one belt splits into three, and the mirrored merge ----------
export const RAILS_W = 192;
export const RAILS_H = 80;
export const RAIL_Y = [8, 40, 72] as const; // centre line of the top (Education), middle (Experience) and bottom (Projects) rail
const SPLIT_X = 56;
const SPLIT_RUN = 32;

function railBand(cv: Cv, yc: (x: number) => number, x0: number, x1: number) {
  for (let x = x0; x < x1; x++) {
    const c = yc(x);
    for (let dy = -5; dy <= 4; dy++) {
      const tread = x % 8 < 2;
      const ch = dy === -5 ? "o" : dy === -4 ? "O" : dy === 3 ? "k" : dy === 4 ? "d" : tread ? "B" : "b";
      put(cv, x, c + dy, ch);
    }
  }
}
function buildRails(withGuide: boolean) {
  const cv = canvas(RAILS_W, RAILS_H);
  const up = (x: number) => (x < SPLIT_X ? 40 : x < SPLIT_X + SPLIT_RUN ? 40 - (x - SPLIT_X) : 8);
  const down = (x: number) => (x < SPLIT_X ? 40 : x < SPLIT_X + SPLIT_RUN ? 40 + (x - SPLIT_X) : 72);
  railBand(cv, up, 0, RAILS_W);
  railBand(cv, down, 0, RAILS_W);
  railBand(cv, () => 40, 0, RAILS_W);
  // the vertical guide the switch carriage slides on, with a detent at each rail
  const gx = 120;
  for (let y = 0; withGuide && y < RAILS_H; y++) {
    put(cv, gx - 1, y, "d");
    put(cv, gx, y, "m");
    put(cv, gx + 1, y, "M");
    put(cv, gx + 2, y, "d");
  }
  for (const y of withGuide ? RAIL_Y : []) {
    put(cv, gx - 2, y - 1, "d"); put(cv, gx - 2, y, "w"); put(cv, gx - 2, y + 1, "d");
    put(cv, gx + 3, y - 1, "d"); put(cv, gx + 3, y, "w"); put(cv, gx + 3, y + 1, "d");
  }
  return rows(cv);
}
export const rails = buildRails(true);
/** The three rails joining back into one belt: the split, mirrored (no switch guide). */
export const merge = buildRails(false).map((r) => [...r].reverse().join(""));
/** The guide's x position and the carriage size (the carriage is centred on the guide). */
export const GUIDE_X = 120;

