  "dcccwwccccCCCd",
  "dccccwwcccCCCd",
  "dcccccwwccCCCd",
  "dcccccwwccCCCd",
  "dccccwwcccCCCd",
  "dcccwwccccCCCd",
  "dccwwccccccCCd",
  "dCCCCCCCCCCCCd",
